schemas:
{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "Berapa lama pelatihan Ahli K3 Umum?",
        "acceptedAnswer": {"@type": "Answer", "text": "Pelatihan Ahli K3 Umum KEMNAKER RI berlangsung selama 12 hari kerja (120 jam pelajaran). Mode online juga tersedia."}
      },
      {
        "@type": "Question",
        "name": "Berapa biaya pelatihan Ahli K3 Umum?",
        "acceptedAnswer": {"@type": "Answer", "text": "Biaya pelatihan Ahli K3 Umum di Wahana Totalita Konsultan mulai dari Rp 7.500.000 per orang, sudah termasuk sertifikasi KEMNAKER RI."}
      },
      {
        "@type": "Question",
        "name": "Apa syarat mengikuti pelatihan Ahli K3 Umum?",
        "acceptedAnswer": {"@type": "Answer", "text": "Syarat utama adalah minimal D3 dengan pengalaman kerja 4 tahun, atau S1 dengan pengalaman minimal 2 tahun, plus dokumen seperti KTP, ijazah, dan surat keterangan kerja."}
      }
    ]
  }

inline_styles:
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Lora:ital,wght@0,400;0,600;1,400&display=swap');

    :root {
      --green-dark: #0A4A2E;
      --green-mid: #1a6b45;
      --green-light: #e8f5ee;
      --accent: #f0a500;
      --text: #1a1a2e;
      --muted: #6b7280;
      --white: #ffffff;
      --border: #e5e7eb;
    }

    * { margin: 0; padding: 0; box-sizing: border-box; }

    body {
      font-family: 'Plus Jakarta Sans', sans-serif;
      color: var(--text);
      background: #fafaf8;
      line-height: 1.7;
    }

    /* NAV */
    nav {
      background: var(--green-dark);
      padding: 16px 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    nav a.logo {
      color: white;
      text-decoration: none;
      font-weight: 800;
      font-size: 1.1rem;
    }
    nav a.cta-nav {
      background: var(--accent);
      color: #1a1a00;
      padding: 8px 18px;
      border-radius: 6px;
      text-decoration: none;
      font-weight: 700;
      font-size: 0.85rem;
    }

    /* HERO */
    .hero {
      background: linear-gradient(135deg, var(--green-dark) 0%, var(--green-mid) 100%);
      color: white;
      padding: 60px 24px 48px;
      text-align: center;
    }
    .hero .tag {
      display: inline-block;
      background: rgba(255,255,255,0.15);
      border: 1px solid rgba(255,255,255,0.3);
      padding: 4px 14px;
      border-radius: 20px;
      font-size: 0.8rem;
      font-weight: 600;
      letter-spacing: 0.05em;
      margin-bottom: 18px;
      text-transform: uppercase;
    }
    .hero h1 {
      font-size: clamp(1.6rem, 4vw, 2.4rem);
      font-weight: 800;
      line-height: 1.25;
      max-width: 700px;
      margin: 0 auto 16px;
    }
    .hero p {
      font-size: 1.05rem;
      opacity: 0.88;
      max-width: 560px;
      margin: 0 auto 28px;
    }
    .hero .meta {
      display: flex;
      gap: 20px;
      justify-content: center;
      flex-wrap: wrap;
      font-size: 0.82rem;
      opacity: 0.75;
    }

    /* LAYOUT */
    .container {
      max-width: 820px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* CONTENT */
    .article-body {
      padding: 48px 0 80px;
    }

    h2 {
      font-size: 1.4rem;
      font-weight: 800;
      color: var(--green-dark);
      margin: 40px 0 14px;
      padding-bottom: 8px;
      border-bottom: 2px solid var(--green-light);
    }
    h3 {
      font-size: 1.1rem;
      font-weight: 700;
      color: var(--text);
      margin: 24px 0 10px;
    }
    p { margin-bottom: 16px; color: #374151; }

    /* INFO BOX */
    .info-box {
      background: var(--green-light);
      border-left: 4px solid var(--green-dark);
      border-radius: 8px;
      padding: 18px 20px;
      margin: 24px 0;
    }
    .info-box strong { color: var(--green-dark); }

    /* STEPS */
    .steps { margin: 24px 0; }
    .step {
      display: flex;
      gap: 16px;
      margin-bottom: 20px;
      align-items: flex-start;
    }
    .step-num {
      width: 36px;
      height: 36px;
      background: var(--green-dark);
      color: white;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 800;
      font-size: 0.9rem;
      flex-shrink: 0;
      margin-top: 2px;
    }
    .step-content h3 { margin-top: 0; font-size: 1rem; }
    .step-content p { margin-bottom: 0; font-size: 0.95rem; }

    /* TABLE */
    table {
      width: 100%;
      border-collapse: collapse;
      margin: 20px 0;
      font-size: 0.92rem;
    }
    th {
      background: var(--green-dark);
      color: white;
      padding: 10px 14px;
      text-align: left;
      font-weight: 600;
    }
    td {
      padding: 10px 14px;
      border-bottom: 1px solid var(--border);
    }
    tr:nth-child(even) td { background: #f9fafb; }

    /* CHECKLIST */
    .checklist { list-style: none; margin: 16px 0; }
    .checklist li {
      padding: 8px 0 8px 28px;
      position: relative;
      border-bottom: 1px solid var(--border);
      font-size: 0.95rem;
    }
    .checklist li:last-child { border-bottom: none; }
    .checklist li::before {
      content: "✓";
      position: absolute;
      left: 0;
      color: var(--green-mid);
      font-weight: 800;
    }

    /* CTA BLOCK */
    .cta-block {
      background: linear-gradient(135deg, var(--green-dark), var(--green-mid));
      color: white;
      border-radius: 16px;
      padding: 36px 28px;
      text-align: center;
      margin: 40px 0;
    }
    .cta-block h3 {
      color: white;
      font-size: 1.3rem;
      margin-bottom: 10px;
    }
    .cta-block p { color: rgba(255,255,255,0.85); margin-bottom: 22px; }
    .btn-wa {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: #25D366;
      color: white;
      padding: 14px 28px;
      border-radius: 8px;
      text-decoration: none;
      font-weight: 700;
      font-size: 1rem;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .btn-wa:hover { transform: translateY(-2px); box-shadow: 0 8px 20px rgba(37,211,102,0.35); }

    /* FAQ */
    .faq-item {
      border: 1px solid var(--border);
      border-radius: 10px;
      margin-bottom: 12px;
      overflow: hidden;
    }
    .faq-q {
      background: white;
      padding: 16px 20px;
      font-weight: 700;
      font-size: 0.95rem;
      cursor: pointer;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
    .faq-q::after { content: "▾"; color: var(--green-mid); }
    .faq-a {
      padding: 14px 20px;
      background: #f9fafb;
      font-size: 0.93rem;
      color: #4b5563;
      border-top: 1px solid var(--border);
    }

    /* BREADCRUMB */
    .breadcrumb {
      padding: 14px 0;
      font-size: 0.82rem;
      color: var(--muted);
    }
    .breadcrumb a { color: var(--green-mid); text-decoration: none; }
    .breadcrumb a:hover { text-decoration: underline; }

    /* FOOTER */
    footer {
      background: var(--green-dark);
      color: rgba(255,255,255,0.75);
      text-align: center;
      padding: 28px 24px;
      font-size: 0.85rem;
    }
    footer a { color: var(--accent); text-decoration: none; }

    /* RELATED */
    .related-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
      gap: 16px;
      margin-top: 16px;
    }
    .related-card {
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 16px;
      background: white;
      text-decoration: none;
      color: var(--text);
      transition: box-shadow 0.2s, transform 0.2s;
    }
    .related-card:hover { box-shadow: 0 4px 16px rgba(0,0,0,0.08); transform: translateY(-2px); }
    .related-card .tag-small {
      font-size: 0.75rem;
      font-weight: 600;
      color: var(--green-mid);
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 6px;
    }
    .related-card h4 { font-size: 0.9rem; font-weight: 700; line-height: 1.3; }

    @media (max-width: 600px) {
      .hero { padding: 40px 16px 32px; }
      h2 { font-size: 1.2rem; }
    }
